// Run: node src/articles.test.mjs
import assert from 'node:assert'
import { parse } from './frontmatter.js'

// folder-based article: slug from directory, bare image paths resolved
const a = parse(
  '---\ntitle: Hello World\ndate: 2024-02-15\nimage: hero.jpg\n---\n# Body\n\n![cap](fig.png)',
  'articles/my-slug/index.md',
)
assert.equal(a.title, 'Hello World')
assert.equal(a.slug, 'my-slug')                       // from the folder name
assert.equal(a.image, '/articles/my-slug/hero.jpg')   // bare hero resolved
assert.equal(a.ogImage, '/articles/my-slug/hero.jpg') // explicit hero is the preview image
assert.ok(a.html.includes('<h1>Body</h1>'))
assert.ok(a.html.includes('src="/articles/my-slug/fig.png"')) // inline image resolved

// video article with no hero: preview falls back to the YouTube thumbnail, no displayed hero
const v = parse(
  '---\ntitle: Talk\ndate: 2024-05-24\n---\n<iframe src="https://www.youtube.com/embed/bLcykUmZNrQ"></iframe>',
  'articles/talk/index.md',
)
assert.equal(v.image, undefined) // nothing rendered as a hero
assert.equal(v.ogImage, 'https://img.youtube.com/vi/bLcykUmZNrQ/maxresdefault.jpg')

// absolute paths and full URLs are left untouched
const b = parse('---\ntitle: T\nimage: /custom/x.jpg\n---\n![a](https://cdn/y.png)', 'articles/t/index.md')
assert.equal(b.image, '/custom/x.jpg')
assert.ok(b.html.includes('src="https://cdn/y.png"'))

// no frontmatter -> still parses, no title
const c = parse('No frontmatter here', 'articles/plain/index.md')
assert.equal(c.slug, 'plain')
assert.ok(!c.title)

console.log('articles parse: OK')

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import fs from 'node:fs'
import path from 'node:path'

const IMAGE_MIME = {
  '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png',
  '.gif': 'image/gif', '.webp': 'image/webp', '.svg': 'image/svg+xml',
}

// Serve images co-located in articles/<slug>/ at /articles/<slug>/<file> during dev.
// In prod, scripts/prerender-articles.mjs copies them into dist/articles/.
function articleImagesDev() {
  return {
    name: 'article-images-dev',
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        const url = req.url.split('?')[0]
        const ext = path.extname(url).toLowerCase()
        if (!url.startsWith('/articles/') || !IMAGE_MIME[ext]) return next()
        const file = path.join(process.cwd(), decodeURIComponent(url))
        if (!fs.existsSync(file) || !fs.statSync(file).isFile()) return next()
        res.setHeader('Content-Type', IMAGE_MIME[ext])
        fs.createReadStream(file).pipe(res)
      })
    },
  }
}

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react(), articleImagesDev()],
  server: {
    watch: {
      usePolling: true,
    },
    host: true,
    strictPort: true,
    port: 5173
  }
})

import React from 'react'
import ReactDOM from 'react-dom/client'
import Clarity from '@microsoft/clarity'
import App from './App'
import './index.css'

// Microsoft Clarity analytics. Project id is configurable via VITE_CLARITY_ID
// (defaults to the maxfelker.com project). Only runs in production builds, so
// dev sessions aren't recorded. Clarity auto-tracks SPA route changes.
const clarityId = import.meta.env.VITE_CLARITY_ID ?? 'x7s0rggs25'
if (import.meta.env.PROD && clarityId) {
  Clarity.init(clarityId)
}

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <App/>
  </React.StrictMode>,
);

import { parse } from './frontmatter'

// Vite reads every Markdown file under /articles at build time — no server, no CMS.
// import.meta.glob is a compile-time macro: it MUST be called unconditionally (no runtime guard).
const files = import.meta.glob('../articles/*/index.md', { query: '?raw', import: 'default', eager: true })

export const articles = Object.entries(files)
  .map(([path, raw]) => parse(raw, path))
  .filter((a) => a.title) // ponytail: skip non-article files like README.md (no frontmatter)
  .sort((a, b) => new Date(b.date) - new Date(a.date))

export const getArticle = (slug) => articles.find((a) => a.slug === slug)

import { marked } from 'marked'

// ponytail: key: value frontmatter only — all our fields are flat. Swap for gray-matter if we ever need nested YAML.
// Lives apart from articles.js so the Node self-check can import it without touching Vite's import.meta.glob.
export function parse(raw, path) {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/)
  const meta = {}
  let body = raw
  if (match) {
    for (const line of match[1].split('\n')) {
      const i = line.indexOf(':')
      if (i > -1) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim()
    }
    body = match[2]
  }

  const slug = meta.slug || slugFromPath(path)

  // Images live next to index.md, so authors reference them by bare filename.
  // Resolve those to the stable served path; leave absolute paths and full URLs alone.
  const resolve = (src) => (/^(https?:|\/)/.test(src) ? src : `/articles/${slug}/${src}`)
  const image = meta.image ? resolve(meta.image) : undefined

  // ponytail: marked output is rendered as-is. Safe because articles are first-party Markdown in this repo, not user input.
  const html = marked.parse(body).replace(/(<img\b[^>]*\bsrc=")([^"]+)(")/g, (_, a, src, b) => a + resolve(src) + b)

  // Link-preview image: an explicit hero wins; otherwise fall back to a YouTube thumbnail
  // when the article embeds a video (so video articles unfurl with a rich card).
  const ogImage = image || youTubeThumbnail(html) || undefined

  return { ...meta, slug, image, html, ogImage }
}

// articles/<slug>/index.md -> <slug>; legacy articles/<slug>.md -> <slug>
function slugFromPath(path) {
  const parts = path.split('/')
  const file = parts.pop()
  return file === 'index.md' ? parts.pop() : file.replace(/\.md$/, '')
}

// Pull the 11-char video id out of an embed/watch/share URL and return its hi-res thumbnail.
export function youTubeThumbnail(html) {
  const m = html.match(/(?:youtube\.com\/embed\/|youtu\.be\/|[?&]v=)([\w-]{11})/)
  return m ? `https://img.youtube.com/vi/${m[1]}/maxresdefault.jpg` : null
}

import {
  createBrowserRouter,
  RouterProvider,
} from "react-router-dom";
import HomePage from "../HomePage";
import AboutPage from '../AboutPage'
import ArticlePage from '../ArticlePage'

const router = createBrowserRouter([
  {
    path: "/",
    element: <HomePage />,
  },
  {
    path: "/about",
    element: <AboutPage />,
  },
  {
    path: "/article/:slug",
    element: <ArticlePage />,
  },
]);

export default function App() {

  return <RouterProvider router={router} />
};

import { useParams, Link } from 'react-router-dom'
import { getArticle } from '../articles'
import styles from './styles.module.css'

export default function ArticlePage() {
  const { slug } = useParams()
  const article = getArticle(slug)

  if (!article) {
    return (
      <div className={styles.content}>
        <h1>Article not found</h1>
        <p><Link to="/">Back home</Link></p>
      </div>
    )
  }

  return (
    <div className={styles.content}>
      <h1>{article.title}</h1>
      <p className={styles.date}>{article.date}</p>
      {article.image && <img className={styles.hero} src={article.image} alt={article.title} />}
      {/* ponytail: first-party Markdown from this repo, not user input — safe to render directly. */}
      <div dangerouslySetInnerHTML={{ __html: article.html }} />
      <p><Link to="/">Back home</Link></p>
    </div>
  )
}

import { Link } from 'react-router-dom'
import styles from './styles.module.css'

export default function ArticleList({ articles }) {
  if (!articles.length) return null

  return (
    <>
      <h2>Latest articles</h2>
      <ul className={styles.articles}>
        {articles.map((article) => (
          <li key={article.slug}>
            <Link to={`/article/${article.slug}`}>{article.title}</Link>
            <p className={styles.meta}>{article.date}</p>
            <p>{article.summary}</p>
          </li>
        ))}
      </ul>
    </>
  )
}
